constexpr uint16_t N = 256;            // power of two, divides 2^16
uint8_t buf[N];
std::atomic<uint16_t> head{0};         // written only by the ISR
std::atomic<uint16_t> tail{0};         // written only by main
std::atomic<uint32_t> overruns{0};

extern "C" void UART_IRQHandler() {
  uint8_t byte = UART->DR;             // reading DR clears the RX flag
  uint16_t h = head.load(std::memory_order_relaxed);
  if (uint16_t(h - tail.load(std::memory_order_acquire)) == N) {
    overruns.fetch_add(1, std::memory_order_relaxed);
    return;                            // full: drop, never block in an ISR
  }
  buf[h % N] = byte;
  head.store(uint16_t(h + 1), std::memory_order_release);
}

bool uart_get(uint8_t& out) {
  uint16_t t = tail.load(std::memory_order_relaxed);
  if (head.load(std::memory_order_acquire) == t) return false;
  out = buf[t % N];
  tail.store(uint16_t(t + 1), std::memory_order_release);
  return true;
}

