extern "C" void SysTick_Handler() {
  ++ticks;
}

uint64_t now() {
  return ticks;
}

volatile uint32_t pending = 0;

extern "C" void EXTI_IRQHandler() {
  ++pending;
}

void loop() {
  uint32_t n = pending;
  handle(n);
  pending -= n;
}

static irqreturn_t my_isr(int irq, void* dev_id) {
  struct mydev* d = dev_id;
  u32 st = readl(d->regs + REG_STATUS);
  writel(st, d->regs + REG_STATUS);  /* W1C */
  napi_schedule(&d->napi);
  return IRQ_HANDLED;
}
